from __future__ import annotations
import argparse,hashlib,json,subprocess
from collections import Counter
from pathlib import Path
from eval.judge.compare_generalization_v0_v1_v2 import metrics

def read(path): return json.loads(path.read_text(encoding="utf8"))
def main(criteria_path:Path,metadata_path:Path,old_comparison:Path,v21_result:Path,out_dir:Path):
    criteria=read(criteria_path); metadata=json.loads(metadata_path.read_text(encoding="utf-8-sig")); old=read(old_comparison); v21=read(v21_result); versions={"v0":old["predictions"]["v0"],"v1":old["predictions"]["v1"],"v2":old["predictions"]["v2"],"v2_1":v21["predictions"]}; scored={k:metrics(v) for k,v in versions.items()}
    by={k:{x["case_id"]:x for x in v} for k,v in versions.items()}; transitions=[]
    for case_id,x in by["v2"].items():
        y=by["v2_1"][case_id]; transitions.append({"case_id":case_id,"gold":x["gold_label"],"challenge_type":x["challenge_type"],"v2_prediction":x["predicted_label"],"v2_1_prediction":y["predicted_label"],"v2_1_reason_code":y["reason_code"],"used_evidence_ids":y["feature_result"].get("used_evidence_ids",[]),"safety_arbitration":y["feature_result"].get("safety_arbitration",{})})
    ts={"v2_unsafe_to_v2_1_correct":sum(x["gold"] in {"PARTIAL","UNSUPPORTED"} and x["v2_prediction"]=="SUPPORTED" and x["v2_1_prediction"]==x["gold"] for x in transitions),"v2_unsafe_to_v2_1_partial_hitl":sum(x["gold"] in {"PARTIAL","UNSUPPORTED"} and x["v2_prediction"]=="SUPPORTED" and x["v2_1_prediction"]=="PARTIAL" for x in transitions),"v2_correct_supported_to_v2_1_false_rejection":sum(x["gold"]=="SUPPORTED" and x["v2_prediction"]=="SUPPORTED" and x["v2_1_prediction"]!="SUPPORTED" for x in transitions),"v2_correct_partial_to_v2_1_regression":sum(x["gold"]=="PARTIAL" and x["v2_prediction"]=="PARTIAL" and x["v2_1_prediction"]!="PARTIAL" for x in transitions),"v2_correct_to_v2_1_wrong":sum(x["v2_prediction"]==x["gold"] and x["v2_1_prediction"]!=x["gold"] for x in transitions),"v2_wrong_to_v2_1_correct":sum(x["v2_prediction"]!=x["gold"] and x["v2_1_prediction"]==x["gold"] for x in transitions),"remaining_unsupported_to_supported":sum(x["gold"]=="UNSUPPORTED" and x["v2_1_prediction"]=="SUPPORTED" for x in transitions)}
    types={}
    for typ in sorted({x["challenge_type"] for x in versions["v2_1"]}):
        types[typ]={"count":sum(x["challenge_type"]==typ for x in versions["v2_1"])}
        for version,rows in versions.items():
            subset=[x for x in rows if x["challenge_type"]==typ]; types[typ][version]={"correct":sum(x["gold_label"]==x["predicted_label"] for x in subset),"accuracy":round(sum(x["gold_label"]==x["predicted_label"] for x in subset)/len(subset),6),"reason_codes":dict(Counter(x.get("reason_code") for x in subset))}
    c=criteria["primary_safety_gates"]|criteria["capability_preservation_gates"]; m=scored["v2_1"]
    gates={"unsafe_acceptance_gate":m["unsafe_acceptance_rate"]<=c["unsafe_acceptance_rate_max"],"conflicting_evidence_gate":types["conflicting_evidence"]["v2_1"]["accuracy"]>=c["conflicting_evidence_accuracy_min"],"insufficient_evidence_gate":types["semantically_related_but_insufficient"]["v2_1"]["accuracy"]>=c["semantically_related_but_insufficient_accuracy_min"],"unsupported_recall_gate":m["unsupported_recall"]>=c["unsupported_recall_min"],"supported_recall_preservation_gate":m["supported_recall"]>=c["supported_recall_min"],"partial_f1_preservation_gate":m["partial_f1"]>=c["partial_f1_min"],"multi_evidence_preservation_gate":types["multi_evidence_support"]["v2_1"]["accuracy"]>=c["multi_evidence_support_accuracy_min"],"macro_f1_gate":m["macro_f1"]>=c["macro_f1_min"]}; gates["overall_pass"]=all(gates.values())
    root=Path(__file__).parents[2]; repo_root=root.parent; head=subprocess.check_output(["git","-c",f"safe.directory={repo_root.as_posix()}","rev-parse","HEAD"],cwd=repo_root,text=True).strip(); criteria_hash=hashlib.sha256(criteria_path.read_bytes()).hexdigest(); impl_hash=hashlib.sha256((root/"services/evidence_judge_v2_1.py").read_bytes()).hexdigest()
    comparison={"provenance":{"dataset_sha256":metadata["dataset_sha256"],"dataset_source_commit":metadata["source_commit_sha"],"git_head":head,"criteria_sha256":criteria_hash,"v2_1_implementation_sha256":impl_hash},"metrics":scored,"failure_type_metrics":types,"transition_summary":ts}
    out_dir.mkdir(parents=True,exist_ok=True); (out_dir/"comparison.json").write_text(json.dumps(comparison,ensure_ascii=False,indent=2)+"\n",encoding="utf8"); (out_dir/"acceptance_result.json").write_text(json.dumps(gates,ensure_ascii=False,indent=2)+"\n",encoding="utf8"); (out_dir/"transitions.json").write_text(json.dumps({"summary":ts,"transitions":transitions,"remaining_unsupported_to_supported":[x for x in transitions if x["gold"]=="UNSUPPORTED" and x["v2_1_prediction"]=="SUPPORTED"]},ensure_ascii=False,indent=2)+"\n",encoding="utf8")
    freeze={"phase":"evidence_judge_v2_1_one_shot_complete","dataset_sha256":metadata["dataset_sha256"],"criteria_sha256":criteria_hash,"implementation_sha256":impl_hash,"git_head":head,"commit_status":"unavailable_due_to_environment_permission_restriction","original_v2_unchanged":True,"second_tuning_forbidden":True}; (out_dir/"freeze_state.json").write_text(json.dumps(freeze,ensure_ascii=False,indent=2)+"\n",encoding="utf8")
    lines=["# Evidence Judge v2.1 Safety Hardening","",f"Acceptance criteria SHA256: `{criteria_hash}`",f"Dataset SHA256: `{metadata['dataset_sha256']}`",f"Implementation SHA256: `{impl_hash}`","", "| Metric | v0 | v1 | v2 | v2.1 |","|---|---:|---:|---:|---:|"]
    for key in ("accuracy","macro_f1","supported_precision","supported_recall","partial_f1","unsupported_recall","unsafe_acceptance_rate","supported_false_rejection_rate","hard_false_rejection_rate","human_review_rate","automation_coverage","selective_accuracy"): lines.append(f"| {key} | {scored['v0'][key]:.6f} | {scored['v1'][key]:.6f} | {scored['v2'][key]:.6f} | {scored['v2_1'][key]:.6f} |")
    lines += ["","## Acceptance", "", "```json",json.dumps(gates,ensure_ascii=False,indent=2),"```","","## Failure Types","","| Type | Count | v0 | v1 | v2 | v2.1 |","|---|---:|---:|---:|---:|---:|"]
    for typ,x in types.items(): lines.append(f"| {typ} | {x['count']} | {x['v0']['accuracy']:.6f} | {x['v1']['accuracy']:.6f} | {x['v2']['accuracy']:.6f} | {x['v2_1']['accuracy']:.6f} |")
    lines += ["","## Final Answers","",f"A. Acceptance gates passed: {gates['overall_pass']}.",f"B. SUPPORTED Recall change: {m['supported_recall']-scored['v2']['supported_recall']:+.6f}; PARTIAL F1 change: {m['partial_f1']-scored['v2']['partial_f1']:+.6f}.",f"C. Freeze and proceed to External Holdout recommendation: {'YES' if gates['overall_pass'] else 'NO'}.","","No second tuning, Judge v3, External Holdout, README claim, or resume update was performed."]
    (out_dir/"summary.md").write_text("\n".join(lines)+"\n",encoding="utf8")
if __name__=="__main__":
    p=argparse.ArgumentParser();
    for n in ("criteria","metadata","old_comparison","v21_result","out_dir"): p.add_argument("--"+n.replace("_","-"),type=Path,required=True)
    a=p.parse_args(); main(a.criteria,a.metadata,a.old_comparison,a.v21_result,a.out_dir)
